using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Linq;using System.Windows.Forms;
namespace BeamScheduleFormatter {
static class FolderTabPainter {
 static int Depth(TabControl tab){int depth=0;for(Control c=tab.Parent;c!=null;c=c.Parent)if(c is TabControl)depth++;return depth;}
 internal static void Draw(TabControl tab,Graphics g,int index,Rectangle bounds){if(index<0||index>=tab.TabCount||bounds.Width<3||bounds.Height<8)return;bool selected=index==tab.SelectedIndex;int depth=Depth(tab);var color=selected?DesktopAppearance.Palette.ActiveTab(depth):DesktopAppearance.Palette.Tab(depth);using(var fill=new SolidBrush(ModernUi.Surface))g.FillRectangle(fill,bounds);var face=new Rectangle(bounds.Left+1,bounds.Top+3,bounds.Width-2,bounds.Height-3);int shoulder=Math.Min(9,face.Width/4);using(var path=new GraphicsPath()){path.AddLines(new[]{new Point(face.Left,face.Bottom),new Point(face.Left,face.Top+6),new Point(face.Left+shoulder,face.Top),new Point(face.Right-shoulder,face.Top),new Point(face.Right,face.Top+6),new Point(face.Right,face.Bottom)});using(var fill=new SolidBrush(color))g.FillPath(fill,path);using(var pen=new Pen(selected?color:PowTheme.Line))g.DrawPath(pen,path);}if(selected)using(var pen=new Pen(color,3))g.DrawLine(pen,face.Left+2,face.Bottom-1,face.Right-2,face.Bottom-1);TextRenderer.DrawText(g,tab.TabPages[index].Text,tab.Font,Rectangle.Inflate(bounds,-8,-3),selected?DesktopAppearance.Palette.ActiveTabText:PowTheme.Ink,TextFormatFlags.NoPrefix|TextFormatFlags.VerticalCenter|TextFormatFlags.HorizontalCenter|TextFormatFlags.SingleLine);}
 internal static void Strip(TabControl tab,Graphics g){if(!PowTheme.IsPrepared(tab)||tab.TabCount==0)return;var rects=Enumerable.Range(0,tab.TabCount).Select(i=>tab.GetTabRect(i)).ToArray();int bottom=Math.Min(tab.ClientSize.Height,rects.Max(r=>r.Bottom)+1);if(bottom<1)return;var state=g.Save();try{g.SetClip(new Rectangle(0,0,tab.ClientSize.Width,bottom));using(var fill=new SolidBrush(ModernUi.Surface))g.FillRectangle(fill,0,0,tab.ClientSize.Width,bottom);for(int i=0;i<rects.Length;i++)if(i!=tab.SelectedIndex)Draw(tab,g,i,rects[i]);if(tab.SelectedIndex>=0)Draw(tab,g,tab.SelectedIndex,rects[tab.SelectedIndex]);/* Owner (17 November 2026): keep a full-width line under the tabs, also when they wrap onto two or more rows. */using(var line=new SolidBrush(DesktopAppearance.Palette.ActiveTab(Depth(tab))))g.FillRectangle(line,0,bottom-2,tab.ClientSize.Width,2);}finally{g.Restore(state);}
  /* no frame lines at the left, right and bottom of the page (owner, 21 November 2026: "alisin na din yung maraming lines sa baba at
     right side" - nested tabs stacked their native 3-D frames) */
  try{var page=tab.DisplayRectangle;var back=tab.SelectedTab!=null?tab.SelectedTab.BackColor:ModernUi.Surface;if(back.A<255||back.IsEmpty)back=ModernUi.Surface;int w=tab.ClientSize.Width,h=tab.ClientSize.Height;
   using(var b=new SolidBrush(back)){if(page.Left>0)g.FillRectangle(b,0,bottom,page.Left,h-bottom);if(page.Right<w)g.FillRectangle(b,page.Right,bottom,w-page.Right,h-bottom);if(page.Bottom<h)g.FillRectangle(b,0,page.Bottom,w,h-page.Bottom);}}catch(Exception){}}
}
}
